<script setup>
import {computed,inject,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Button,Empty,Modal} from 'ant-design-vue'
import {useObservationRead} from './observabilityState.js'
import {finalSources,listQuery,statusLabel,stagesFor,tableTarget,validIdentity} from './observabilityModel.js'
import ReadState from '../document/ReadState.vue'
import Facts from '../document/Facts.vue'
import ObservationContent from './ObservationContent.vue'
import './observability.css'
const props=defineProps({conversationId:String,exchangeId:String}),route=useRoute(),router=useRouter(),container=inject('admin-next-container')
const detail=useObservationRead('exchange'),session=useObservationRead('session'),retrieval=useObservationRead('retrieval'),channels=useObservationRead('channels'),benchmarks=useObservationRead('benchmarks'),inspector=ref(null)
const payload={conversationId:props.conversationId,exchangeId:props.exchangeId},tabs=[['overview','概览'],['retrieval','检索与融合'],['evidence','证据与引用'],['prompt','Prompt 与性能']],tab=computed(()=>tabs.some(([k])=>k===route.query.tab)?route.query.tab:'overview')
const exchange=computed(()=>detail.data.value?.exchange||session.data.value?.exchanges?.find(x=>validIdentity(x.exchangeId)===props.exchangeId)),stages=computed(()=>detail.data.value?.stageTraces||[]),sources=computed(()=>finalSources(exchange.value?.references)),contextRows=computed(()=>(Array.isArray(retrieval.data.value)?retrieval.data.value:[]).filter(x=>x.contextOnly===true||x.citationEvidenceType==='CONTEXT_ONLY'))
const candidates=computed(()=>Array.isArray(retrieval.data.value)?retrieval.data.value:[]),executions=computed(()=>Array.isArray(channels.data.value)?channels.data.value:[])
let loadedRetrieval=false,loadedBenchmarks=false,trigger,alive=true
onBeforeUnmount(()=>{alive=false})
function loadTab(){if(['retrieval','evidence'].includes(tab.value)&&!loadedRetrieval){loadedRetrieval=true;retrieval.read(payload);channels.read(payload)}if(tab.value==='prompt'&&!loadedBenchmarks){loadedBenchmarks=true;benchmarks.read({})}}
function inspect(title,value,event){trigger=event.currentTarget;inspector.value={title,value};nextTick(()=>{if(alive)document.querySelector('.admin-next-observe-inspector')?.focus()})}
function restore(){requestAnimationFrame(()=>{if(alive&&trigger?.isConnected)trigger.focus({preventScroll:true})})}
onMounted(()=>{detail.read(payload);session.read({conversationId:props.conversationId});loadTab()});watch(tab,loadTab)
</script>
<template><section class="admin-next-observe"><RouterLink :to="{name:'AdminObservationSession',params:{conversationId},query:{...listQuery($route.query),turnPage:$route.query.turnPage,listAnchor:$route.query.listAnchor}}">← 返回会话轮次列表</RouterLink><h1>轮次详情</h1><p class="admin-next-observe-muted">{{ exchangeId }}</p><ReadState :state="detail" label="轮次详情" @retry="detail.read(payload)" /><ReadState :state="session" label="会话摘要" @retry="session.read({conversationId})" /><Empty v-if="!detail.loading.value&&!session.loading.value&&!exchange" description="未找到当前轮次" /><template v-if="exchange"><header class="admin-next-observe-panel"><h2>{{ exchange.question||'未记录问题' }}</h2><p>{{ statusLabel(exchange.status) }} · 首次响应 {{ exchange.firstResponseTimeMs??'未记录' }} ms · 总耗时 {{ exchange.totalResponseTimeMs??'未记录' }} ms</p><p v-if="exchange.errorMessage" role="status">{{ exchange.errorMessage }}</p><details><summary>范围与轮次元数据</summary><Facts :value="Object.fromEntries(Object.entries(exchange).filter(([key])=>!['answer','debugTrace','references'].includes(key)))" /></details></header><nav class="admin-next-observe-toolbar" aria-label="轮次详情分类"><Button v-for="[value,label] in tabs" :key="value" :type="tab===value?'primary':'text'" :aria-current="tab===value?'page':undefined" @click="router.replace({query:{...$route.query,tab:value}})">{{ label }}</Button></nav>
<section v-show="tab==='overview'" class="admin-next-observe-panel"><h2>回答</h2><ObservationContent :text="exchange.answer||''" markdown label="回答" /><h2>阶段轨迹</h2><ul class="admin-next-observe-list"><li v-for="(stage,index) in stages" :key="stage.stageId||index"><Button @click="inspect(stage.stageName||stage.stageCode,stage,$event)">{{ stage.stageName||stage.stageCode }}</Button><p>{{ statusLabel(stage.stageState) }} · {{ stage.durationMs??'未记录' }} ms</p><p>{{ stage.summaryText }}</p></li></ul><p v-if="!stages.length">未记录阶段轨迹</p></section>
<section v-if="tab==='retrieval'" class="admin-next-observe-panel"><h2>检索与融合</h2><ReadState :state="retrieval" label="检索候选" @retry="retrieval.read(payload)" /><ReadState :state="channels" label="通道执行" @retry="channels.read(payload)" /><h3>通道执行</h3><ul class="admin-next-observe-list"><li v-for="(item,index) in executions" :key="item.id||index"><Button @click="inspect('通道执行',item,$event)">{{ item.channelType||'未记录通道' }}</Button><p>状态 {{ ({1:'成功',2:'失败',3:'超时',4:'跳过'}[item.executionState]||'未记录') }} · 耗时 {{ item.durationMs??'未记录' }} ms</p><p>召回 {{ item.recalledCount??'—' }} · 接受 {{ item.acceptedCount??'—' }} · 最终选中 {{ item.finalSelectedCount??'—' }}</p><p v-if="item.errorMessage">{{ item.errorMessage }}</p></li></ul><Empty v-if="channels.data.value&&!executions.length" description="暂无通道执行" /><h3>候选与排序</h3><ul class="admin-next-observe-list"><li v-for="(item,index) in candidates" :key="item.id||index"><Button @click="inspect('候选详情',item,$event)">{{ item.documentName||item.candidateId||'候选 '+(index+1) }}</Button><p>{{ item.channelType||'未记录通道' }} · 原分数 {{ item.originalScore??'—' }} · RRF {{ item.rrfScore??'—' }} · 重排 {{ item.rerankScore??'—' }} · 最终排名 {{ item.finalRank??'—' }}</p><p>{{ item.contextOnly?'Context Only':item.citationEvidenceType||'未记录证据类型' }} · {{ item.selectionReason||item.filteredReason||'未记录筛选原因' }}</p><p>{{ item.chunkTextPreview }}</p></li></ul><Empty v-if="retrieval.data.value&&!candidates.length" description="暂无检索候选" /><details v-for="stage in stagesFor(stages,'RAG_RETRIEVE')" :key="stage.stageId"><summary>检索阶段快照</summary><Facts :value="stage.snapshot" /></details></section>
<section v-if="tab==='evidence'" class="admin-next-observe-panel"><h2>最终绑定来源</h2><ul class="admin-next-observe-list"><li v-for="item in sources" :key="item.referenceId+':'+item.citationIdentity"><Button @click="inspect('来源 '+item.referenceId,item,$event)">[{{ item.referenceId }}] {{ item.documentName||item.title||item.citationIdentity }}</Button><p>{{ item.citationIdentity }}</p><p>{{ item.quoteText||item.snippet }}</p><RouterLink v-if="(item.tableId||item.tableNo)&&tableTarget(item)" :to="tableTarget(item)">定位表格命中</RouterLink></li></ul><p v-if="!sources.length">暂无具有稳定身份与原编号的绑定来源</p><h3>Context Only</h3><ReadState :state="retrieval" label="检索候选" @retry="retrieval.read(payload)" /><ul class="admin-next-observe-list"><li v-for="(item,index) in contextRows" :key="index"><p>{{ item.documentName||item.contextIdentity||'上下文' }}</p><p>{{ item.chunkTextPreview }}</p><details><summary>上下文元数据</summary><Facts :value="item" /></details></li></ul><p v-if="!contextRows.length">未记录 Context Only</p><section v-for="[code,label] in [['EVIDENCE_BUDGET','Prompt 证据预算与渲染'],['CITATION_BINDING','显式引用绑定与守恒'],['FINALIZE','最终归档快照']]" :key="code"><h3>{{ label }}</h3><details v-for="stage in stagesFor(stages,code)" :key="stage.stageId"><summary>{{ stage.stageName||code }}</summary><Facts :value="stage.snapshot" /></details><p v-if="!stagesFor(stages,code).length">未记录</p></section><details><summary>后端来源原始记录</summary><Facts :value="exchange.references" /></details></section>
<section v-if="tab==='prompt'" class="admin-next-observe-panel"><h2>Prompt 与性能</h2><h3>System Prompt</h3><ObservationContent :text="exchange.debugTrace?.ragSystemPrompt||''" label="System Prompt" /><h3>User Prompt</h3><ObservationContent :text="exchange.debugTrace?.ragUserPrompt||''" label="User Prompt" /><details><summary>模型使用与调试信息</summary><Facts :value="exchange.debugTrace" /></details><h3>阶段基准</h3><ReadState :state="benchmarks" label="阶段基准" @retry="benchmarks.read({})" /><p>仅展示服务端返回的基准记录，不补全缺失耗时。</p><details v-for="(item,index) in (Array.isArray(benchmarks.data.value)?benchmarks.data.value:[])" :key="index"><summary>{{ item.stageCode||item.stageName||'阶段 '+(index+1) }}</summary><Facts :value="item" /></details><p v-if="Array.isArray(benchmarks.data.value)&&!benchmarks.data.value.length">暂无阶段基准</p></section>
</template><Modal wrap-class-name="admin-next-observe-inspector" :open="Boolean(inspector)" :title="inspector?.title" :width="900" :get-container="container" :footer="null" destroy-on-close @cancel="inspector=null" :after-close="restore"><div class="admin-next-observe-dialog"><Facts v-if="inspector" :value="inspector.value" /></div></Modal></section></template>

